//! 🔤️ Actual UTF8 copy completion owns the only transferable output across every cancellation cut.
use super::*;
use crate::observe_retirement_allocations as observe;
use semio_framework_test_fixtures::fixture_text;
use semio_framework_value_clone_source_testing::{FixtureSource,FixtureSourceBirth,FixtureCloseStep,observe_fixture_source_allocations};
#[path="producer.rs"] mod producer;
use producer::{Harness,Op};
fn grant(d:crate::RetirementDemand,body:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body.max(d.copy_bytes),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn assert_no_take(source:&mut FixtureSource<String>,cursor:&mut Harness<String>){let occupied=cursor.has_output();let max=source.wallet().remaining_work();let(d,work)=cursor.quote(source,Op::Take,0,max);let issued=grant(d,0);let(step,heap)=cursor.drive(source,Op::Take,0,max,issued,work);assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(cursor.has_output(),occupied);}
#[test]
fn string_clone_output_waits_for_complete_owned_payload_and_closes_each_cut(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../../🧬️retained-clone/🧬️contract/🔤️string-cursor/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for row in law["closeGrants"].as_array().unwrap(){let d=&row["demand"];let g=&row["grant"];let demand=crate::RetirementDemand{copy_bytes:d["copyBytes"].as_u64().unwrap()as usize,capacity_bytes:d["capacityBytes"].as_u64().unwrap()as usize,release_bytes:d["releaseBytes"].as_u64().unwrap()as usize,depth:d["depth"].as_u64().unwrap()as usize};let issued=RetainedCloneGrant{maximum_items:g["items"].as_u64().unwrap()as usize,maximum_copy_bytes:g["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["depth"].as_u64().unwrap()as usize};assert_eq!(retained_clone_grant_admits(issued,demand),row["accepted"].as_bool().unwrap());}
 for row in law["texts"].as_array().unwrap(){let text=row["text"].as_str().unwrap().repeat(row["repeat"].as_u64().unwrap()as usize);for body in law["bodyBytes"].as_array().unwrap(){let body=body.as_u64().unwrap()as usize;for cut in law["cancelCuts"].as_array().unwrap(){for close_first in law["closeBeforeTake"].as_array().unwrap(){
  let(mut source,heap)=observe_fixture_source_allocations(||RetainedCloneSource::<String>::from_owner(text.clone()));assert!(heap.0>0);assert_eq!(heap.1,0);let original=source.borrow().get().as_ptr();let mut cursor=Harness::new(&source);assert!(!cursor.ready());assert!(!cursor.has_output());assert_no_take(&mut source,&mut cursor);let mut complete=false;let mut turns=0;let mut selected_body=body;let maximum=text.len().checked_mul(8).and_then(|n|n.checked_add(1024)).unwrap();
  while !complete&&cut.as_u64().is_none_or(|cut|turns<cut as usize){let max=source.wallet().remaining_work();let(d,work)=cursor.quote(&source,Op::Advance,selected_body,max);let issued=grant(d,selected_body);let(step,heap)=cursor.drive(&mut source,Op::Advance,selected_body,max,issued,work);if work==0&&d==RetirementDemand::default(){assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));selected_body=law["retryBody"].as_u64().unwrap()as usize;}assert!(step.progress().fits(issued));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));complete=matches!(step,RetainedCloneStep::Complete(_));assert_eq!(cursor.ready(),complete,"partial reservation/copy cannot transfer the original string output");if !complete{assert!(!cursor.has_output());assert_no_take(&mut source,&mut cursor);}assert_eq!(source.borrow().get().as_ptr(),original);turns+=1;assert!(turns<maximum);}
  if complete&&!close_first.as_bool().unwrap(){let max=source.wallet().remaining_work();let(d,work)=cursor.quote(&source,Op::Take,0,max);let issued=grant(d,0);let(step,heap)=cursor.drive(&mut source,Op::Take,0,max,issued,work);assert!(matches!(step,RetainedCloneStep::Complete(_)));assert_eq!(heap,(0,0));assert!(cursor.output_matches(text.as_str()));assert!(!cursor.ready());assert!(cursor.has_output());assert_no_take(&mut source,&mut cursor);}
  let max=source.wallet().remaining_work();let(d,work)=cursor.quote(&source,Op::Start,0,max);let issued=grant(d,0);cursor.drive(&mut source,Op::Start,0,max,issued,work);assert!(!cursor.ready());assert_no_take(&mut source,&mut cursor);let(mut close_turns,mut close_idle)=(0,0);while !cursor.terminal(){let max=source.wallet().remaining_work();let(d,work)=cursor.quote(&source,Op::Close,4096,max);let mut issued=grant(d,0);issued.maximum_items=source.wallet().remaining().maximum_items;let(step,heap)=cursor.drive(&mut source,Op::Close,4096,max,issued,work);assert!(step.progress().fits(issued));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));let unchanged=step.progress()==Default::default()&&!cursor.terminal()&&cursor.quote(&source,Op::Close,4096,source.wallet().remaining_work()).0==d;close_idle=if unchanged{close_idle+1}else{0};assert!(close_idle<law["maximumIdleTurns"].as_u64().unwrap()as usize,"String close underquoted its actual selected transition: {d:?}");close_turns+=1;assert!(close_turns<law["closeTurns"].as_u64().unwrap()as usize);}
  let mut output_turns=0;while cursor.has_output()||!cursor.output_close_empty(){let op=if cursor.has_output(){Op::OutputStart}else{Op::OutputClose};let max=source.wallet().remaining_work();let(d,work)=cursor.quote(&source,op,4096,max);let mut issued=grant(d,0);issued.maximum_items=source.wallet().remaining().maximum_items;let(step,heap)=cursor.drive(&mut source,op,4096,max,issued,work);assert!(step.progress().fits(issued));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));output_turns+=1;assert!(output_turns<law["closeTurns"].as_u64().unwrap()as usize);}cursor.release(&mut source);assert_eq!(observe_fixture_source_allocations(||drop(cursor)).1,(0,0));
  let(mut source_turns,mut idle)=(0,0);let mut observed=(0usize,0usize);while !source.terminal_is_empty(){let d=source.next_close_demand(4096).unwrap();assert!(d.copy_bytes<=4096);let mut issued=grant(d,4096);issued.maximum_items=source.wallet().remaining().maximum_items;let(state,heap)=observe_fixture_source_allocations(||source.close_with(4096,issued).unwrap());observed.0=observed.0.checked_add(heap.0).unwrap();observed.1=observed.1.checked_add(heap.1).unwrap();let progress=match state{FixtureCloseStep::Progress(progress)=>progress,FixtureCloseStep::Complete=>Default::default(),FixtureCloseStep::Pending=>{source_turns+=1;assert!(source_turns<law["closeTurns"].as_u64().unwrap()as usize);continue},FixtureCloseStep::Denied|FixtureCloseStep::Blocked=>panic!("source exact paid close was not admitted: {d:?}")};assert!(progress.fits(issued));assert_eq!(observed,(progress.retained_capacity_bytes,progress.released_bytes));observed=(0,0);let unchanged=progress==Default::default()&&!source.terminal_is_empty()&&source.next_close_demand(4096).unwrap()==d;idle=if unchanged{idle+1}else{0};source_turns+=1;assert!(idle<law["maximumIdleTurns"].as_u64().unwrap()as usize,"source repeated an unchanged receipt and quote: {d:?}, len={}, cut={cut}",text.len());assert!(source_turns<law["closeTurns"].as_u64().unwrap()as usize,"source exceeded constant String Bytes/frame closure work: {d:?}, len={}, cut={cut}",text.len());}assert_eq!(observe_fixture_source_allocations(||drop(source)).1,(0,0));
 }}}}
}

#[test]
fn bound_string_close_returns_the_original_alias_under_the_same_source(){
 let law:serde_json::Value=serde_json::from_str(include_str!("bound-close.json")).unwrap();
 let(mut source,_)=observe_fixture_source_allocations(||RetainedCloneSource::<String>::from_owner(law["text"].as_str().unwrap().to_owned()));
 let original=source.borrow().get().as_ptr();let mut cursor=Harness::new(&source);let maximum=source.wallet().remaining_work();
 let(d,work)=cursor.quote(&source,Op::Advance,0,maximum);let issued=grant(d,0);cursor.drive(&mut source,Op::Advance,0,maximum,issued,work);
 let(d,work)=cursor.quote(&source,Op::Start,0,maximum);cursor.drive(&mut source,Op::Start,0,maximum,grant(d,0),work);
 let(d,work)=cursor.quote(&source,Op::BoundClose,0,maximum);assert_eq!(work,law["selectedWork"].as_u64().unwrap());assert!(d.copy_bytes>0);
 let mut short=grant(d,0);short.maximum_copy_bytes=d.copy_bytes-1;let(step,heap)=cursor.drive(&mut source,Op::BoundClose,0,maximum,short,work);assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert!(!cursor.terminal());assert_eq!(source.borrow().get().as_ptr(),original);
 let(step,heap)=cursor.drive(&mut source,Op::BoundClose,0,maximum,grant(d,0),work);assert!(step.progress().fits(grant(d,0)));assert_eq!(heap,(0,0));assert!(cursor.terminal());assert_eq!(source.borrow().get().as_ptr(),original);cursor.release(&mut source);
 let mut turns=0;while !source.terminal_is_empty(){let d=source.next_close_demand(4096).unwrap();let mut issued=grant(d,4096);issued.maximum_items=source.wallet().remaining().maximum_items;let(state,heap)=observe_fixture_source_allocations(||source.close_with(4096,issued).unwrap());if let FixtureCloseStep::Progress(progress)=state{assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));}turns+=1;assert!(turns<law["maximumCloseTurns"].as_u64().unwrap());}
}
